export interface ChatSession {
  id: string
  companyId: string
  title: string
  messages: Array<{
    id: string
    role: 'user' | 'assistant'
    content: string
    timestamp: string
    thinking?: string
    images?: string[]
    referenceFiles?: string[]
  }>
  createdAt: string
  updatedAt: string
  claudeSessionId?: string
  draftInput?: string
  titleAutoGenerated?: boolean
  pinned?: boolean
  pinnedAt?: string
  writerId?: string
  writeSequence?: number
  revision?: number
}

export type ChatMetadataPatch = Partial<Pick<ChatSession,
  'title' | 'titleAutoGenerated' | 'pinned' | 'claudeSessionId'>>

export type ChatSaveResult =
  | { status: 'saved'; session: ChatSession }
  | { status: 'conflict'; session: ChatSession }
  | { status: 'deleted' }

export interface ChatHistoryChange {
  companyId: string
  deletedSessionId?: string
}
